subroutine CountLarger(data[] as integer by reference, size as integer, bound as integer) as integer
    define i as integer;
    define counter as integer;
    counter <- 0;
    for i <- 0 to size - 1 step 1 do
        if data[i] > bound then
            counter <- counter + 1;
        endIf
    endFor
    return counter;
endSubroutine

algorithm RunCount
    dimension vector[5] as integer;
    define i as integer;
    define bound as integer;
    for i <- 0 to 4 step 1 do
        read vector[i];
    endFor
    read bound;
    write CountLarger(vector, 5, bound);
endAlgorithm
